    b_intervals = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_intervals:
        return []

    if not b_intervals:
        return a_intervals

    # Merge overlapping/touching intervals in b for efficient subtraction
    merged_b = []
    for start, end in b_intervals:
        if merged_b and start <= merged_b[-1][1]:
            merged_b[-1][1] = max(merged_b[-1][1], end)
        else:
            merged_b.append([start, end])

    result = []

    for a_start, a_end in a_intervals:
        current_start = a_start

        # Process each b interval that overlaps with current a interval
        for b_start, b_end in merged_b:
            if b_end <= current_start:
                # b interval is completely before current position
                continue
            if b_start >= a_end:
                # b interval is completely after current a interval
                break

            # b interval overlaps with [current_start, a_end)
            if current_start < b_start:
                # Add the part before b interval
                result.append([current_start, b_start])

            # Move current_start past the b interval
            current_start = max(current_start, b_end)

        # Add any remaining part of a interval
        if current_start < a_end:
            result.append([current_start, a_end])

    # Merge touching intervals in result
    merged_result = []
